      ? tools.some(tool => tool?.name === FRAME_CONN_DM_SCENE_CONTROL_NAME)
      : Boolean(tools?.[FRAME_CONN_DM_SCENE_CONTROL_NAME]);

    if (!exists) {
      const dmTool = {
        name: FRAME_CONN_DM_SCENE_CONTROL_NAME,
        title: "Frame Conn // Mission",
        icon: "fa-solid fa-map",
        order: Array.isArray(tools) ? tools.length : Object.keys(tools ?? {}).length,
        button: true,
        visible: true,
        onChange: () => frameConnFoundryIntegrationRuntimeBindings.openDmApplication()
      };

      if (Array.isArray(tools)) tools.push(dmTool);
      else {
        tokenControls.tools ??= {};
        tokenControls.tools[FRAME_CONN_DM_SCENE_CONTROL_NAME] = dmTool;
      }
      changed = true;
    }
  }

  return changed;
}


